const rwLessonData = {
0:['Guhitamo site: Guhitamo ahantu hakwiye gukorerwa FLR','Kumenya uko Field Officer asuzuma ahantu hashobora gukorerwa ibikorwa bya FLR.','Ubumenyi bw’ingenzi kuri Field Officer','','',''],
1:['Amahame ya FLR no kureba imiterere y’ahantu hose','Gusobanukirwa uburyo bwo guhuza gusana ibidukikije n’ibikenewe n’abaturage.','Amahame shingiro',
'<p>FLR ikoresha uburyo bwo kureba ahantu hose nk’urusobe ruhuza imirima, amashyamba, imisozi, ibibaya, inkombe z’imigezi n’indi mikoreshereze y’ubutaka. Intego ni ukugarura imikorere y’ibidukikije no guteza imbere imibereho y’abaturage mu gihe kirekire.</p><p>Ibikorwa bigomba gutegurwa hakurikijwe imiterere y’aho hantu, ibyifuzo by’abaturage, ubutaka, amazi, ibimera bisanzwe n’ibikorwa bihasanzwe. Gutera ibiti byinshi byonyine si byo bipimo byonyine byerekana ko FLR yageze ku ntego.</p>',
'Mu ruzinduko, reba umurima mu miterere y’ahawukikije: ubuhaname, imikoreshereze y’ubutaka, inzira z’amazi, ibimera bihari n’ibyo abaturage bakeneye. Menya niba igikorwa giteganyijwe gihuye n’aho hantu, kandi ugeze ibyemezo bya tekiniki ku itsinda ribishinzwe.',
'<a href="https://greenfund.rw/sites/default/files/2021-06/Forest%20Landscape%20Restoration%20Opportunity%20Assessment%20for%20Rwanda.pdf" target="_blank" rel="noopener">Isuzuma ry’amahirwe yo gusana ibidukikije mu Rwanda</a>'],
2:['Ubuhinzi bw’ibiti n’ibihingwa','Gusobanura uko ibiti bishobora gufasha umusaruro w’ubuhinzi, kwihanganira imihindagurikire n’ibikenerwa n’urugo.','Ubumenyi bwa tekiniki',
'<p>Ubuhinzi bw’ibiti n’ibihingwa ni uburyo bwo guhuza ibiti n’imyaka cyangwa amatungo mu micungire y’ubutaka bumwe. Ibiti bishobora gufasha kurwanya isuri, gukomeza amaterasi, kongera uburumbuke bw’ubutaka, gutanga imbuto, ubwatsi, imbaho cyangwa inkwi.</p><p>Inyungu ziterwa n’ubwoko bw’igiti, aho gitewe, uko cyitabwaho n’icyo umuhinzi agikeneyeho. Nta bwoko bumwe bw’igiti bukwiriye ahantu hose.</p>',
'Banza ubaze umuhinzi icyo yifuza ku giti kandi usuzume aho azagiterera. Reba igicucu gishobora kugira ku bihingwa, imizi, ubuhaname, ubutaka, amazi n’ubwoko bwemejwe muri gahunda. Ntugire ubwoko cyangwa intera yo gutera utanga utabanje kugenzura amabwiriza y’umushinga.',
'<a href="https://www.rfa.rw/fileadmin/user_upload/RFA/Publications/4.REPORTS_AND_PUBLICATIONS/NATIONAL_AGROFORESTRY_STRATEGY_Fin-1.pdf" target="_blank" rel="noopener">Ingamba z’u Rwanda zo guteza imbere ubuhinzi bw’ibiti n’ibihingwa</a>'],
3:['Kubungabunga ubutaka n’amazi','Kumenya ibimenyetso by’isuri n’uburyo bwo kubungabunga ubutaka n’amazi.','Ibikorwa byo mu murima',
'<p>Mu Rwanda, ibikorwa byo gusana ibishanga n’amasoko y’amazi bishobora guhuza ubuhinzi bw’ibiti, kurwanya isuri, amaterasi n’uturere turinda inkombe z’imigezi. Ku butaka buhanamye, ibimera n’ingamba zo kubungabunga ubutaka bishobora kugabanya gutwarwa k’ubutaka no gufasha amazi kwinjira mu butaka.</p><p>Uburyo bukwiye bushingira ku buhaname, ubwoko bw’ubutaka, imvura, imikoreshereze y’ubutaka n’igishushanyo cya tekiniki cyemewe.</p>',
'Mu murima, reba imigende y’amazi, imikoki y’isuri, ubutaka bwambaye ubusa, amaterasi yangiritse, inzira amazi anyuramo n’ahakikije imigezi. Andika ibyo wabonye. Imirimo y’amaterasi cyangwa indi myubakire isaba igishushanyo cya tekiniki igomba gukorwa n’ababifitiye ubumenyi.',
'<a href="https://www.waterportal.rwb.rw/toolbox/503" target="_blank" rel="noopener">Urubuga rw’amazi mu Rwanda: Gusana ibice by’ikusanyirizo ry’amazi</a> · <a href="https://waterportal.rwb.rw/index.php/toolbox/462" target="_blank" rel="noopener">Amashyamba n’ubuhinzi bw’ibiti</a>'],
4:['Pepinière n’ubuziranenge bw’ingemwe','Kumenya ibimenyetso by’ingemwe nzima n’uko zitwarwa neza.','Ubumenyi bwa tekiniki',
'<p>Gahunda yo gutera ibiti igira amahirwe menshi yo gutsinda iyo ikoresheje ingemwe nziza kandi zijyanye n’ahantu zizaterwa. Mu igenzura, harebwa amababi n’igiti bizima, uruti rukomeye, imizi ikuze neza, kutagira udukoko cyangwa indwara bikomeye, n’ingano ijyanye n’ubwoko bw’igiti.</p><p>Ibipimo nyabyo by’ubuziranenge bigomba gukurikiza amabwiriza yihariye ya pepinière n’ubwoko bw’igiti.</p>',
'Mbere yo gukwirakwiza ingemwe, genzura uko zimeze ukoresheje urutonde rwemewe. Tandukanya ubwoko n’umubare w’ingemwe kugira ngo bikurikiranwe. Zirinde kuma, kumeneka cyangwa kwangirika mu gihe cyo kuzitwara. Ingamba zo kwanga cyangwa gutanga raporo ku ngemwe zitameze neza zigomba gukurikiza amabwiriza y’umushinga.',
'<a href="https://oneacrefund.org/what-we-do/areas-focus/trees/tree-program-impact-country" target="_blank" rel="noopener">One Acre Fund: Gahunda y’ibiti mu Rwanda</a> · <a href="https://www.rfa.rw/projects/fip-prodar" target="_blank" rel="noopener">Ikigo cy’Igihugu gishinzwe Amashyamba: FIP-PRODAR</a>'],
5:['Guhitamo ubwoko bw’ibiti bujyanye n’ahantu','Gusobanukirwa impamvu ubwoko bw’igiti bugomba guhuye n’imiterere y’ahantu n’icyo umuhinzi agikeneyeho.','Ubumenyi bwa tekiniki',
'<p>Ubwoko bw’ibiti butandukanye mu mazi bukenera, imizi, imiterere yabyo, umuvuduko wo gukura, umusaruro bitanga n’uko bihanganira imiterere y’aho bitewe. Bimwe bifasha ubutaka, ibindi bigatanga imbuto, ubwatsi, imbaho cyangwa inkwi.</p><p>Nta bwoko bumwe bukwiriye ahantu hose. Guhitamo bigomba gushingira ku miterere y’aho hantu, intego y’umuhinzi n’urutonde rw’ubwoko rwemejwe n’umushinga.</p>',
'Genzura urutonde rw’ubwoko bwemejwe n’amabwiriza ya tekiniki agezweho. Reba aho umuhinzi azatera, icyo igiti kigenewe n’ipaki yemewe. Ntugasimbuze ubwoko cyangwa ngo usezeranye umusaruro utabiherewe amakuru yemewe.',
'<a href="https://www.rfa.rw/fileadmin/user_upload/RFA/Publications/4.REPORTS_AND_PUBLICATIONS/NATIONAL_AGROFORESTRY_STRATEGY_Fin-1.pdf" target="_blank" rel="noopener">Ingamba z’u Rwanda zo guteza imbere ubuhinzi bw’ibiti n’ibihingwa</a>'],
6:['Gutegura aho gutera, gutera no kwita ku biti','Gusobanura intambwe zikurikizwa kuva aho gutera hategurwa kugeza ku kwita ku ngemwe zimaze guterwa.','Ibikorwa byo mu murima',
'<p>Gutera neza bitangirira ku myiteguro. Ahantu n’uburyo bwo gutera bigomba gukurikiza ipaki yemewe n’amabwiriza ajyanye n’ubwoko bw’igiti. Gutwara ingemwe neza, gutera mu gihe gikwiye, kurinda imizi, gukanda ubutaka neza no gukurikirana ingemwe nyuma yo gutera bigira uruhare mu mikurire yazo.</p>',
'Koresha urutonde rw’ibikorwa byo gutera rwemejwe na Tubura FLR. Emeza aho ibiti bizaterwa, urinde ingemwe kuma, wirinde kwangiza imizi kandi usobanurire umuhinzi uko azazifata neza. Tanga raporo ku ngemwe zabuze, zangiritse, ziragirirwa cyangwa izindi mbogamizi.',
'<a href="https://oneacrefund.org/what-we-do/building-resilience/training" target="_blank" rel="noopener">One Acre Fund: Amahugurwa y’abahinzi</a>'],
7:['Guhugura abahinzi no kuyobora ibikorwa byo mu murima','Gutegura amahugurwa y’abahinzi ashingiye ku kwerekana no gukora imyitozo.','Ubushobozi bwa Field Officer',
'<p>Amahugurwa meza ahuza gusobanura, kwerekana uko igikorwa gikorwa, guha abahinzi umwanya wo kugerageza, kwakira ibitekerezo no kubakurikirana. Amahugurwa agomba gusubiza ibibazo by’abahinzi kandi agahuye n’imiterere y’aho batuye.</p>',
'Tegura intego isobanutse y’isomo. Koresha urugero rufatika cyangwa werekane igikorwa, saba abahinzi kugaragaza ibyo basobanukiwe, genzura ko ubutumwa bwumvikanye, andika abitabiriye neza kandi mwumvikane ku ruzinduko rukurikiraho. Irinde ibiganiro by’umuntu umwe bitagenzura niba abahinzi babyumvise.',
'<a href="https://oneacrefund.org/what-we-do/building-resilience/training" target="_blank" rel="noopener">One Acre Fund: Amahugurwa</a>'],
8:['Gukurikirana ibiti byatanzwe, ibyatewe n’ibyarokotse','Gutandukanya umubare w’ingemwe zatanzwe, ibiti byatewe n’ibiti bikiri bizima.','Gukurikirana no gusuzuma',
'<p>Ingemwe zatanzwe, ibiti byatewe n’ibiti bikiri bizima ni ibipimo bitandukanye. Raporo yo gutanga ingemwe igaragaza izahawe cyangwa zakiriwe. Igenzura ryo gutera rigaragaza izatewe. Igenzura ry’irokoka rireba ibiti bikiri bizima nyuma y’igihe runaka cyagenwe.</p><p>Gupima ibiti byatewe byonyine ntibihagije kwemeza ko ibiti byarokotse cyangwa ko intego zose zagezweho.</p>',
'Andika neza ubwoko bw’igipimo, itariki, umuhinzi cyangwa site, uburyo bwo kubara cyangwa gufata icyitegererezo n’ibimenyetso. Ntukavuge ko ingemwe zatanzwe ari zo zatewe, cyangwa ngo izatewe uzite ibyarokotse. Koresha uburyo bwo gukora survey bwemejwe n’umushinga.',
'<a href="https://oneacrefund.org/publications/2023-2024-rwanda-agroforestry-rct-final-report" target="_blank" rel="noopener">Isuzuma rya gahunda y’ubuhinzi bw’ibiti mu Rwanda (2023–2024)</a>'],
9:['Ubuziranenge bw’amakuru, kurengera abantu no gutanga raporo','Kubika amakuru yizewe, ashobora kugenzurwa kandi yubahiriza ibanga ry’abahinzi.','Imyitwarire ya kinyamwuga',
'<p>Amakuru yo mu murima agomba kugira ibisobanuro bisobanutse, amatariki ahuye, inkomoko izwi kandi akagaragaza ukuri. Raporo igomba gutandukanya ibyo Field Officer yiboneye n’ibyo yabwiwe cyangwa yagereranije. Nta mibare igomba guhimbwa.</p><p>Amakuru yihariye y’abahinzi agomba kubikwa no gukoreshwa gusa mu buryo bwemewe, hakurikijwe uburenganzira n’amabwiriza yo kurinda amakuru.</p>',
'Genzura amazina n’imibare ugereranyije n’inyandiko zemewe. Kosora ibitandukanye mbere yo kohereza raporo, andika inkomoko ya buri mubare kandi urinde amakuru y’abahinzi. Niba hari amakuru atabonetse, yandike ko abura aho kuyahimba, hanyuma ukurikize inzira yo kuyuzuza.',
'<span>Amabwiriza y’imbere ya Tubura FLR n’amabwiriza yo kurinda amakuru ni byo bigomba gukurikizwa.</span>'],
10:['Tubura na One Acre Fund: gahunda y’ibiti mu Rwanda','Gusobanukirwa aho gahunda y’ibiti ihuriye n’imbaraga zo gusana ibidukikije mu Rwanda.','Imiterere ya gahunda',
'<p>One Acre Fund (izwi nka Tubura mu Rwanda) ikorana n’abahinzi mu guteza imbere umusaruro n’imibereho yabo, harimo ibikorwa bijyanye n’ibiti n’ubuhinzi bwabyo. Amakuru rusange y’umuryango agaragaza ibikorwa n’ibyagezweho ku rwego rwa gahunda, ariko ibyo si imibare yihariye y’umushinga wa FLR ukoreramo.</p><p>Field Officer agomba gutandukanya imibare rusange y’igihugu n’intego, umubare w’abahinzi cyangwa ibiti by’umushinga ashinzwe.</p>',
'Mu kazi ka buri munsi, koresha gusa intego, urutonde rw’ibiti, ipaki, ibipimo n’amabwiriza yahawe umushinga wawe. Ntukoreshe imibare rusange yo ku rubuga nk’aho ari imibare y’akarere kawe cyangwa site yawe.',
'<a href="https://oneacrefund.org/what-we-do/areas-focus/trees/tree-program-impact-country" target="_blank" rel="noopener">One Acre Fund: Ibyagezweho na gahunda y’ibiti mu Rwanda</a>']
};
function rwLesson(i,l){const d=rwLessonData[i];return d?[l[0],l[1],l[2],l[3],l[4],l[5]].map((v,j)=>d[j]):l}
