$('#nav').addEventListener('click',e=>{let b=e.target.closest('button[data-page]');if(b)go(b.dataset.page)});$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#langBtn').onclick=()=>{lang=lang==='en'?'rw':'en';localStorage.setItem('flr_lang',lang);$('#langBtn').textContent=lang==='en'?'Kinyarwanda':'English';render()};
